namespace App\Console\Commands;

use Illuminate\Console\Command;

/**
 * $DESCRIPTION_SUMMARY$
 */
class $CLASS_NAME$ extends Command
{
    /**
     * The name and signature of the console command.
     *
     * @var string
     */
    protected $signature = '$COMMAND_NAME$
        {$ARG_NAME$ : $ARG_DESCRIPTION$}
        {--run : このオプションを指定した場合のみ本実行を行う(未指定時はドライラン)}';

    /**
     * The console command description.
     *
     * @var string
     */
    protected $description = '$DESCRIPTION_SUMMARY$
        ・$PROCESS_1$
        ・$PROCESS_2$';

    /**
     * Execute the console command.
     *
     * @return int
     */
    public function handle(): int
    {
        $this->info("[$COMMAND_NAME$] 処理を開始します。");

        $isRun = (bool)$this->option('run');
        $targetPath = $this->argument('$ARG_NAME$');

        if (!$isRun) {
            $this->comment('【DRY RUN】本実行時は --run オプションを付与してください。');
        }

        try {
            // $END$

        } catch (\Exception $e) {
            $this->error("[$COMMAND_NAME$] エラーが発生しました。");
            $this->error($e->getMessage());
            return self::FAILURE;
        }

        $this->info("[$COMMAND_NAME$] 正常終了しました。");
        return self::SUCCESS;
    }
}
